 	@JoinColumn(name = "type_id")
 	private PetType type;

+	@Column
+	private String microchipNumber;
+
 	@OneToMany(cascade = CascadeType.ALL, fetch = FetchType.EAGER)
 	@JoinColumn(name = "pet_id")
 	@OrderBy("date ASC")
@@ -74,6 +77,19 @@ public class Pet extends NamedEntity {
 		this.type = type;
 	}

+	public String getMicrochipNumber() {
+		return this.microchipNumber;
+	}
+
+	/**
+	 * Trims the value and removes its spaces. Any other character is kept, so that the
+	 * validator rejects it. An empty result is stored as no microchip number.
+	 */
+	public void setMicrochipNumber(String microchipNumber) {
+		String normalised = (microchipNumber != null) ? microchipNumber.trim().replace(" ", "") : null;
+		this.microchipNumber = (normalised == null || normalised.isEmpty()) ? null : normalised;
+	}
+
 	public Collection<Visit> getVisits() {
 		return this.visits;
 	}
