diff --git a/src/main/java/org/springframework/samples/petclinic/owner/PetValidator.java b/src/main/java/org/springframework/samples/petclinic/owner/PetValidator.java
index cd0c807..3366d70 100644
--- a/src/main/java/org/springframework/samples/petclinic/owner/PetValidator.java
+++ b/src/main/java/org/springframework/samples/petclinic/owner/PetValidator.java
@@ -16,6 +16,7 @@
 package org.springframework.samples.petclinic.owner;

 import java.time.LocalDate;
+import java.util.regex.Pattern;

 import org.springframework.util.StringUtils;
 import org.springframework.validation.Errors;
@@ -37,6 +38,17 @@ public class PetValidator implements Validator {

 	private static final int MAX_NAME_LENGTH = 30;

+	private static final String MICROCHIP_NUMBER = "microchipNumber";
+
+	// [0-9] rather than \d, so the rule cannot widen to other digit characters.
+	private static final Pattern MICROCHIP_NUMBER_FORMAT = Pattern.compile("[0-9]{15}");
+
+	private final PetRepository pets;
+
+	public PetValidator(PetRepository pets) {
+		this.pets = pets;
+	}
+
 	@Override
 	public void validate(Object obj, Errors errors) {
 		Pet pet = (Pet) obj;
@@ -61,6 +73,35 @@ public class PetValidator implements Validator {
 		else if (pet.getBirthDate().isAfter(LocalDate.now())) {
 			errors.rejectValue("birthDate", "typeMismatch.birthDate");
 		}
+
+		// microchip number validation: optional, and at most one error. The uniqueness
+		// query runs only for a well-formed number, never for a pet without one.
+		String microchipNumber = pet.getMicrochipNumber();
+		if (microchipNumber != null) {
+			if (!MICROCHIP_NUMBER_FORMAT.matcher(microchipNumber).matches()) {
+				errors.rejectValue(MICROCHIP_NUMBER, "microchipNumber.invalid");
+			}
+			else if (isMicrochipNumberTakenByAnotherPet(pet)) {
+				rejectDuplicateMicrochipNumber(errors);
+			}
+		}
+	}
+
+	/**
+	 * Rejects the microchip number as a duplicate. The controller calls this when the
+	 * database's unique constraint catches a duplicate that validation could not see. The
+	 * error names no other pet or owner.
+	 */
+	public void rejectDuplicateMicrochipNumber(Errors errors) {
+		errors.rejectValue(MICROCHIP_NUMBER, "duplicate");
+	}
+
+	private boolean isMicrochipNumberTakenByAnotherPet(Pet pet) {
+		// A new pet has no id, and "id <> NULL" never matches, so it needs its own query.
+		if (pet.isNew()) {
+			return this.pets.existsByMicrochipNumber(pet.getMicrochipNumber());
+		}
+		return this.pets.existsByMicrochipNumberAndIdNot(pet.getMicrochipNumber(), pet.getId());
 	}

 	/**
