package org.springframework.samples.petclinic.owner;

import org.springframework.data.repository.Repository;

/**
 * Repository class for <code>Pet</code> domain objects. It holds only the queries that
 * the microchip number check in {@link PetValidator} needs.
 */
public interface PetRepository extends Repository<Pet, Integer> {

	/**
	 * Whether any pet has the given microchip number. Used for a new pet, which has no id
	 * yet.
	 */
	boolean existsByMicrochipNumber(String microchipNumber);

	/**
	 * Whether any pet other than the one with the given id has the given microchip
	 * number. Used for an existing pet, so that it never conflicts with its own number.
	 */
	boolean existsByMicrochipNumberAndIdNot(String microchipNumber, Integer id);

}

-- PC-301: add the microchip number to an existing MySQL pets table.
-- Run this by hand AFTER release 1 (seed inserts with column lists) is deployed, with no
-- older instance left running, and BEFORE release 2 (the microchip number) is deployed.
-- Rollback from release 2 redeploys release 1 and leaves the column and constraint.
ALTER TABLE pets ADD COLUMN microchip_number VARCHAR(15) NULL;
ALTER TABLE pets ADD CONSTRAINT unique_pet_microchip_number UNIQUE (microchip_number);

-- PC-301: add the microchip number to an existing Postgres pets table.
-- Run this by hand AFTER release 1 (seed inserts with column lists) is deployed, with no
-- older instance left running, and BEFORE release 2 (the microchip number) is deployed.
-- Rollback from release 2 redeploys release 1 and leaves the column and index.
ALTER TABLE pets ADD COLUMN IF NOT EXISTS microchip_number TEXT;
CREATE UNIQUE INDEX IF NOT EXISTS unique_pet_microchip_number ON pets (microchip_number);

